/** Where products rows are kept. Services depend only on this interface. */
interface ProductRepository {
    /** The row with this primary key, or null. */
    fun findById(id: Long): Product?

    /** At most limit rows from offset, by primary key, and how many there are. */
    fun list(offset: Int, limit: Int): Page<Product>

    /** Rows with this category_id, by primary key. */
    fun listByCategoryId(categoryId: Int): List<Product>

    /** Stores a new row; the values the database fills are read back. */
    fun insert(entity: Product): Product

    /** Stores the changes made to a row. */
    fun update(entity: Product): Product

    /** Removes a row. */
    fun delete(entity: Product): Unit
}

